CREATE OR REPLACE FUNCTION public.complete_wake_protocol(_slot text,_task_id uuid DEFAULT NULL) RETURNS TABLE(coins integer,streak integer,longest_streak integer,awarded integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Solve the server-issued alarm challenge to complete Wake Protocol' USING ERRCODE='42501'; END; $$;
CREATE OR REPLACE FUNCTION public.complete_wake_selfie(_uid uuid,_tz text) RETURNS TABLE(coins integer,streak integer,longest_streak integer,awarded integer,result text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Wake Protocol requires the server-issued math or science solve; camera verification is not used' USING ERRCODE='42501'; END; $$;
CREATE OR REPLACE FUNCTION public.complete_alarm(_alarm_id uuid,_reward integer DEFAULT 10) RETURNS TABLE(coins integer,awarded integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); day date:=(now() AT TIME ZONE 'utc')::date; pts integer; inserted boolean; label text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF; SELECT a.label INTO label FROM public.alarms a WHERE a.id=_alarm_id AND a.user_id=u; IF NOT FOUND THEN RAISE EXCEPTION 'alarm not found'; END IF; IF label='AXEN Wake Protocol' THEN RAISE EXCEPTION 'Solve the server-issued wake challenge' USING ERRCODE='42501'; END IF; pts:=least(10,public.axen_daily_coin_room(u)); PERFORM set_config('app.economy_write','on',true); INSERT INTO public.alarm_sessions(user_id,alarm_id,completed_on,coins_awarded) VALUES(u,_alarm_id,day,pts) ON CONFLICT(user_id,alarm_id,completed_on) DO NOTHING; inserted:=FOUND; IF inserted AND pts>0 THEN UPDATE public.profiles p SET coins=p.coins+pts WHERE p.id=u; INSERT INTO public.coin_transactions(user_id,amount,reason,ref_id) VALUES(u,pts,'alarm',_alarm_id); END IF; SELECT p.coins INTO coins FROM public.profiles p WHERE p.id=u; awarded:=CASE WHEN inserted THEN pts ELSE 0 END; RETURN NEXT; END; $$;
CREATE OR REPLACE FUNCTION public.save_wake_plan(_slot text,_tone text,_mode text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result jsonb; t time; BEGIN IF _slot NOT IN ('4AM','5AM','6AM','7AM') THEN RAISE EXCEPTION 'invalid wake slot'; END IF; t:=(lpad(left(_slot,1),2,'0')||':00')::time; result:=public.wake_save_settings(t,'20:30'::time,_tone,_mode,true,true,2::smallint); RETURN (result->>'alarm_id')::uuid; END; $$;
CREATE OR REPLACE FUNCTION public.guard_wake_alarm_fields() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP='INSERT' AND (NEW.label='AXEN Wake Protocol' OR NEW.wake_saved_at IS NOT NULL) THEN RAISE EXCEPTION 'Use wake settings' USING ERRCODE='42501'; END IF; IF TG_OP='UPDATE' AND (OLD.label='AXEN Wake Protocol' OR NEW.label='AXEN Wake Protocol' OR OLD.wake_saved_at IS NOT NULL OR NEW.wake_saved_at IS NOT NULL) THEN RAISE EXCEPTION 'Use the server-owned wake settings' USING ERRCODE='42501'; END IF; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.wake_subscribe(_endpoint text,_p256dh text,_auth text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; IF length(_endpoint)>2048 OR _endpoint!~'^https://(fcm[.]googleapis[.]com|updates[.]push[.]services[.]mozilla[.]com|([a-zA-Z0-9-]+[.])*push[.]apple[.]com|([a-zA-Z0-9-]+[.])*notify[.]windows[.]com)/' OR _p256dh!~'^[A-Za-z0-9_-]{87}=?$' OR _auth!~'^[A-Za-z0-9_-]{22}={0,2}$' THEN RAISE EXCEPTION 'invalid subscription'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74011)); IF (SELECT count(*) FROM public.wake_push_subscriptions WHERE user_id=u)>=10 AND NOT EXISTS(SELECT 1 FROM public.wake_push_subscriptions WHERE endpoint=_endpoint AND user_id=u) THEN RAISE EXCEPTION 'subscription limit'; END IF; INSERT INTO public.wake_push_subscriptions(user_id,endpoint,p256dh,auth_key) VALUES(u,_endpoint,_p256dh,_auth) ON CONFLICT(endpoint) DO UPDATE SET p256dh=EXCLUDED.p256dh,auth_key=EXCLUDED.auth_key WHERE wake_push_subscriptions.user_id=u; IF NOT FOUND THEN RAISE EXCEPTION 'Subscription belongs to another account' USING ERRCODE='42501'; END IF; END; $$;
COMMENT ON FUNCTION public.complete_wake_protocol(text,uuid) IS 'DEPRECATED: completion is exclusively through wake_submit_answer; signature retained to fail closed for older clients.';
COMMENT ON FUNCTION public.complete_wake_selfie(uuid,text) IS 'DEPRECATED: no camera wake flow; completion exclusively through wake_submit_answer.';
COMMENT ON TABLE public.alarm_events IS 'Private server-owned occurrences and answer keys. No browser SELECT/INSERT/UPDATE policies by design.';